import '../domain/task.dart';

class TaskListPage extends ConsumerStatefulWidget {
  const TaskListPage({super.key});

  @override
  ConsumerState<TaskListPage> createState() => _TaskListPageState();
}

class _TaskListPageState extends ConsumerState<TaskListPage> {
  final _searchController = TextEditingController();
  TaskFilter _filter = TaskFilter.all;
  String _query = '';

  @override
  void dispose() {
    _searchController.dispose();
    super.dispose();
  }

  Future<void> _openEditor({Task? task}) => showDialog<void>(
        context: context,
        builder: (_) => TaskEditorDialog(
          initialTitle: task?.title ?? '',
          onSave: (title) => task == null
              ? ref.read(taskListProvider.notifier).add(title).map((_) => true)
              : ref
                  .read(taskListProvider.notifier)
                  .update(task.id, title)
                  .map((_) => true),
        ),
      );

  Future<void> _confirmDelete(Task task) async {
    final shouldDelete = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text('Delete task?'),
        content: Text('“${task.title}” will be removed from this list.'),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(context, true),
            child: const Text('Delete'),
          ),
        ],
      ),
    );
    if (shouldDelete case true) {
      ref.read(taskListProvider.notifier).delete(task.id);
    }
  }

  @override
  Widget build(BuildContext context) {
    final user = ref.watch(authProvider);
    final allTasks = ref.watch(taskListProvider);
    final visibleTasks = filterTasks(allTasks, _filter, _query);
    final remaining = allTasks.where((task) => !task.isComplete).length;

    return Scaffold(
      appBar: AppBar(
        title: const Text('Daybook'),
        actions: [
          IconButton(
            key: const Key('sign-out-button'),
            tooltip: 'Sign out',
            onPressed: ref.read(authProvider.notifier).signOut,
            icon: const Icon(Icons.logout),
          ),
        ],
      ),
      body: Center(
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 720),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 20, 16, 8),
                child: Text(
                  'Hello, ${user?.displayName ?? 'friend'}',
                  style: Theme.of(context).textTheme.headlineSmall,
                ),
              ),
              Padding(
                padding: const EdgeInsets.symmetric(horizontal: 16),
                child: Text(
                  remaining == 1 ? '1 task left' : '$remaining tasks left',
                  key: const Key('remaining-task-count'),
                ),
              ),
              Padding(
                padding: const EdgeInsets.all(16),
                child: TextField(
                  key: const Key('task-search-input'),
                  controller: _searchController,
                  onChanged: (query) => setState(() => _query = query),
                  decoration: InputDecoration(
                    labelText: 'Find a task',
                    prefixIcon: const Icon(Icons.search),
                    border: const OutlineInputBorder(),
                    suffixIcon: _query.isEmpty
                        ? null
                        : IconButton(
                            tooltip: 'Clear search',
                            onPressed: () {
                              _searchController.clear();
                              setState(() => _query = '');
                            },
                            icon: const Icon(Icons.clear),
                          ),
                  ),
                ),
              ),
              Padding(
                padding: const EdgeInsets.symmetric(horizontal: 16),
                child: Wrap(
                  spacing: 8,
                  children: TaskFilter.values
                      .map(
                        (filter) => ChoiceChip(
                          label: Text(_filterLabel(filter)),
                          selected: _filter == filter,
                          onSelected: (_) => setState(() => _filter = filter),
                        ),
                      )
                      .toList(growable: false),
                ),
              ),
              Expanded(
                child: visibleTasks.isEmpty
                    ? Center(
                        child: Text(
                          allTasks.isEmpty
                              ? 'Your list is empty. Add a task to get started.'
                              : 'No tasks match this view.',
                          textAlign: TextAlign.center,
                        ),
                      )
                    : ListView(
                        padding: const EdgeInsets.all(16),
                        children: visibleTasks
                            .map(
                              (task) => Card(
                                child: CheckboxListTile(
                                  key: ValueKey('task-${task.id}'),
                                  title: Text(task.title),
                                  value: task.isComplete,
                                  onChanged: (value) {
                                    if (value case final bool isComplete) {
                                      ref
                                          .read(taskListProvider.notifier)
                                          .setCompletion(task.id, isComplete);
                                    }
                                  },
                                  secondary: Row(
                                    mainAxisSize: MainAxisSize.min,
                                    children: [
                                      IconButton(
                                        tooltip: 'Edit ${task.title}',
                                        onPressed: () =>
                                            _openEditor(task: task),
                                        icon: const Icon(Icons.edit_outlined),
                                      ),
                                      IconButton(
                                        tooltip: 'Delete ${task.title}',
                                        onPressed: () => _confirmDelete(task),
                                        icon: const Icon(Icons.delete_outline),
                                      ),
                                    ],
                                  ),
                                ),
                              ),
                            )
                            .toList(growable: false),
                      ),
              ),
            ],
          ),
        ),
      ),
      floatingActionButton: FloatingActionButton.extended(
        key: const Key('add-task-button'),
        onPressed: () => _openEditor(),
        icon: const Icon(Icons.add),
        label: const Text('Add task'),
      ),
    );
  }
}

String _filterLabel(TaskFilter filter) => switch (filter) {
      TaskFilter.all => 'All',
      TaskFilter.active => 'To do',
      TaskFilter.complete => 'Done',
    };

class TaskEditorDialog extends StatefulWidget {
  const TaskEditorDialog({
    required this.initialTitle,
    required this.onSave,
    super.key,
  });

  final String initialTitle;
  final Either<TaskFailure, bool> Function(String title) onSave;

  @override
  State<TaskEditorDialog> createState() => _TaskEditorDialogState();
}

class _TaskEditorDialogState extends State<TaskEditorDialog> {
  late final _titleController = TextEditingController(
    text: widget.initialTitle,
  );
  String? _errorMessage;

  @override
  void dispose() {
    _titleController.dispose();
    super.dispose();
  }

  void _save() => widget.onSave(_titleController.text).match(
        (failure) => setState(() => _errorMessage = switch (failure) {
              TaskFailure.titleRequired => 'Enter a task title.',
              TaskFailure.taskNotFound => 'This task is no longer available.',
            }),
        (_) => Navigator.pop(context),
      );

  @override
  Widget build(BuildContext context) => AlertDialog(
        title: Text(widget.initialTitle.isEmpty ? 'Add a task' : 'Edit task'),
        content: TextField(
          key: const Key('task-title-input'),
          autofocus: true,
          controller: _titleController,
          textCapitalization: TextCapitalization.sentences,
          onSubmitted: (_) => _save(),
          decoration: InputDecoration(
            labelText: 'Task title',
            border: const OutlineInputBorder(),
            errorText: _errorMessage,
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('Cancel'),
          ),
          FilledButton(onPressed: _save, child: const Text('Save')),
        ],
      );
}
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:fpdart/fpdart.dart' hide Task;

import '../domain/auth.dart';
import '../domain/task.dart';

final authProvider = NotifierProvider<AuthController, DemoUser?>(
  AuthController.new,
);

final taskListProvider = NotifierProvider<TaskListController, List<Task>>(
  TaskListController.new,
);

class AuthController extends Notifier<DemoUser?> {
  @override
  DemoUser? build() => null;

  Either<SignInFailure, DemoUser> signIn(String email, String password) {
    final result = signInDemoUser(email, password);
    result.match((_) {}, (user) => state = user);
    return result;
  }

  void signOut() => state = null;
}

class TaskListController extends Notifier<List<Task>> {
  @override
  List<Task> build() => sampleTasks;

  Either<TaskFailure, Task> add(String title) {
    final result = createTask(
      id: DateTime.now().microsecondsSinceEpoch.toString(),
      title: title,
    );
    result.match((_) {}, (task) => state = addTask(state, task));
    return result;
  }

  Either<TaskFailure, List<Task>> update(String taskId, String title) {
    final result = updateTask(state, taskId, title);
    result.match((_) {}, (tasks) => state = tasks);
    return result;
  }

  void setCompletion(String taskId, bool isComplete) =>
      state = setTaskCompletion(state, taskId, isComplete);

  void delete(String taskId) => state = deleteTask(state, taskId);
}
import 'package:fpdart/fpdart.dart';

enum TaskFailure { titleRequired, taskNotFound }

enum TaskFilter { all, active, complete }

final class Task {
  const Task({required this.id, required this.title, this.isComplete = false});

  final String id;
  final String title;
  final bool isComplete;

  Task withCompletion(bool value) =>
      Task(id: id, title: title, isComplete: value);

  Task withTitle(String value) =>
      Task(id: id, title: value, isComplete: isComplete);
}

const sampleTasks = <Task>[
  Task(id: 'sample-1', title: 'Review the week'),
  Task(id: 'sample-2', title: 'Buy groceries'),
  Task(id: 'sample-3', title: 'Call Sam', isComplete: true),
];

Either<TaskFailure, Task> createTask({
  required String id,
  required String title,
}) =>
    switch (title.trim()) {
      '' => left(TaskFailure.titleRequired),
      final normalizedTitle => right(Task(id: id, title: normalizedTitle)),
    };

List<Task> addTask(List<Task> tasks, Task task) =>
    List.unmodifiable([...tasks, task]);

Either<TaskFailure, List<Task>> updateTask(
  List<Task> tasks,
  String taskId,
  String title,
) =>
    createTask(id: taskId, title: title).flatMap(
      (updated) => tasks.any((task) => task.id == taskId)
          ? right(
              List.unmodifiable(
                tasks.map((task) =>
                    task.id == taskId ? task.withTitle(updated.title) : task),
              ),
            )
          : left(TaskFailure.taskNotFound),
    );

List<Task> setTaskCompletion(
  List<Task> tasks,
  String taskId,
  bool isComplete,
) =>
    List.unmodifiable(
      tasks.map(
        (task) => task.id == taskId ? task.withCompletion(isComplete) : task,
      ),
    );

List<Task> deleteTask(List<Task> tasks, String taskId) =>
    List.unmodifiable(tasks.where((task) => task.id != taskId));

List<Task> filterTasks(List<Task> tasks, TaskFilter filter, String query) =>
    List.unmodifiable(
      tasks.where((task) {
        final matchesFilter = switch (filter) {
          TaskFilter.all => true,
          TaskFilter.active => !task.isComplete,
          TaskFilter.complete => task.isComplete,
        };
        return matchesFilter &&
            task.title.toLowerCase().contains(query.trim().toLowerCase());
      }),
    );
import 'package:flutter_test/flutter_test.dart';

import 'package:daybook/domain/task.dart';

void main() {
  test('adding a task keeps existing tasks and appends the new task', () {
    const added = Task(id: 'new', title: 'Plan tomorrow');

    final result = addTask(sampleTasks, added);

    expect(result.map((task) => (task.id, task.title, task.isComplete)), [
      ...sampleTasks.map((task) => (task.id, task.title, task.isComplete)),
      (added.id, added.title, added.isComplete),
    ]);
    expect(sampleTasks, hasLength(3));
  });

  test('changing completion updates only the matching task', () {
    final result = setTaskCompletion(sampleTasks, 'sample-1', true);

    expect(result.first.isComplete, isTrue);
    expect(result.skip(1), sampleTasks.skip(1));
    expect(sampleTasks.first.isComplete, isFalse);
  });

  test('changing an unknown task leaves the list unchanged', () {
    final result = setTaskCompletion(sampleTasks, 'missing', true);

    expect(
      result.map((task) => (task.id, task.title, task.isComplete)),
      sampleTasks.map((task) => (task.id, task.title, task.isComplete)),
    );
  });
}

